style.css:
@-moz-document domain("google.com"), domain("www.google.com") {
/* Altera o fundo da página do Google para a imagem personalizada */
    body {
        background-image: url('https://wallpaperwaifu.com/wp-content/uploads/2025/06/seele-x-bronya-rest-time-honkai-impact-3rd-thumb-1500x844.jpg');
        background-size: cover; /* Ajusta a imagem para cobrir toda a tela */
        background-position: center; /* Centraliza a imagem */
        background-attachment: fixed; /* Faz a imagem ficar fixa enquanto a página rola */
        color: #000; /* Cor do texto */
    }

    input[type="text"] {
        background-color: rgba(255, 255, 255, 0.8);
        color: #333;
    }

    input[type="submit"] {
        background-color: #4CAF50;
        color: white;
    }

    #gb {
        background-color: rgba(255, 255, 255, 0.7);
    }

    a {
        color: #1a73e8;
    }
}
